(r, big) => {
    const pool = ["sun", "moon", "star", "sky", "sea", "a", "an", "it", "sunny", "rays"];
    const k = big ? 10 : r.int(1, 4);
    const words = r.shuffle(pool.slice()).slice(0, k);
    const banned = words.filter((_, i) => i > 0 && r.bool(0.4));
    const counts = words.map(() => r.int(1, big ? 30 : 3));
    // words[0] is never banned; make it the unique winner among allowed words
    let top = 0;
    for (let i = 1; i < k; i++) if (!banned.includes(words[i])) top = Math.max(top, counts[i]);
    counts[0] = Math.max(counts[0], top + 1);
    const tokens = [];
    words.forEach((w, i) => { for (let c = 0; c < counts[i]; c++) tokens.push(w); });
    const seps = [" ", ", ", "!", "?", ". ", ";", "'", "  "];
    const text = r.shuffle(tokens).map(w => r.bool() ? w.toUpperCase() : (r.bool() ? w[0].toUpperCase() + w.slice(1) : w)).map((w, i) => (i ? r.pick(seps) : "") + w).join("");
    return [text, banned.concat(r.bool(0.3) ? ["zzz"] : [])];
  }

