function topAllowedWord(text: string, banned: string[]): string {
  const ban = new Set(banned);
  const count = new Map<string, number>();
  for (const w of text.toLowerCase().split(/[^a-z]+/)) {
    if (w && !ban.has(w)) count.set(w, (count.get(w) || 0) + 1);
  }
  let best = "", most = 0;
  for (const [w, c] of count) if (c > most) { best = w; most = c; }
  return best;
}

