class Solution:
    def topAllowedWord(self, text: str, banned: List[str]) -> str:
        ban = set(banned)
        cleaned = "".join(c if c.isalpha() else " " for c in text.lower())
        count = Counter(w for w in cleaned.split() if w not in ban)
        return count.most_common(1)[0][0]

