class Solution:
    def topAllowedWord(self, text: str, banned: List[str]) -> str:
        ban = set(banned)
        count = defaultdict(int)
        best, most, cur = "", 0, []

        def flush():
            nonlocal best, most
            w = "".join(cur)
            cur.clear()
            if w and w not in ban:
                count[w] += 1
                if count[w] > most:
                    best, most = w, count[w]

        for ch in text:
            if ch.isalpha():
                cur.append(ch.lower())
            else:
                flush()
        flush()
        return best

